    "المبيعات الناجحة": "Successful sales",
    "المصروف يحتسب للعمليات الناجحة بتكلفة موثقة برد الشركة فقط. قيمة قائمة الشركة وقت الطلب ليست تسوية فعلية؛ إذا وجدت تكلفة غير موثقة يبقى الإجمالي غير معلوم.": "The expense is calculated for successful operations at a documented cost with the company’s return only. The Company's list value at the time of order is not an actual settlement; If there is an undocumented cost, the total remains unknown.",
    "مجموع مبالغ بيع العمليات الناجحة فقط ضمن نطاقك، عبر جميع التواريخ. الطلبات المعلقة والمرتجعة لا تدخل في هذا المجموع.": "The sum of the sale amounts of only successful transactions within your domain, across all dates. Pending and returned orders are not included in this total.",
