    "ضوابط أوقات المستخدمين لمالك حساب مدير النظام مع صلاحيات الأمن وضوابطه فقط.": "User time controls belong to the system administrator account owner with security powers and controls only.",
    "يتطلب سجل قرارات الإيقاف حساب النظام وصلاحيات عرض الأمن والتدقيق.": "The log of suspension decisions requires a system account and viewing security and auditing permissions.",
    "لا يوجد سجل حجز مستقل لطلبات التمويل؛ حجوزات البيع تظهر في تقرير حجوزات البطاقات.": "There is no independent reservation record for financing applications; Sale reservations appear in the Card Reservations report.",
