    "تكلفة الشركة مخفية عن نقطة البيع؛ لا يوجد سعر شراء مستقل يتيح احتساب ربحها دون كشف هذه التكلفة.": "The company's cost is hidden from the point of sale; There is no independent purchase price that allows calculating its profit without revealing this cost.",
    "التكلفة الموثقة برد الشركة فقط. سعر كتالوج Topup وقت الطلب ليس تكلفة تسوية فعلية؛ الربح لا يحتسب للطلبات غير المكتملة.": "Only the documented cost will be refunded by the company. The Topup catalog price at the time of order is not an actual settlement cost; Profit is not calculated for incomplete orders.",
