    "جلب فئات الشركة": "پۆلەکانی کۆمپانیا بهێنە",
    "اتصلنا بالشركة بنجاح، لكن الشركة أعادت قائمة فئات فارغة لهذا التوكن. اطلب من المزود تفعيل الشركات والفئات لحسابك ثم اضغط جلب فئات الشركة. توفر الرصيد وحده لا يعني توفر فئات للبيع.": "ئێمە بە سەرکەوتوویی پەیوەندیمان بە کۆمپانیاکە کرد، بەڵام کۆمپانیاکە لیستێکی بەتاڵی بۆ ئەم تۆکنە گەڕاندەوە. داوا لە دابینکەرەکە بکە کۆمپانیا و پۆلەکان بۆ ئەکاونتەکەت چالاک بکات، پاشان کلیک لە Get company categories بکە. بەردەستبوونی قەرز بە تەنیا بە مانای بەردەستبوونی پۆلەکان نییە بۆ فرۆشتن.",
