    "نتيجة العملية غير مؤكدة؛ أعد المحاولة من الزر نفسه، أو راجع السجل قبل بدء عملية جديدة.": "دەرئەنجامی نەشتەرگەرییەکە نادیارە؛ لە هەمان دوگمەوە هەوڵبدەرەوە، یان پێش دەستپێکردنی کارێکی نوێ پێداچوونەوە بە لۆگەکەدا بکە.",
