    "'اتصال بـ' + row.label + ' ' + row.number": "'پەیوەندی بە' + ڕیز.ناوی + ' ' + ڕیز.ژمارە",
    "\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"ماسال\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>": "",
    "مرتجعة": "گەڕایەوە",
    "مبلغ المبيع": "بڕی فرۆشتن",
    "المصروف لدى الشركة": "خەرجی لەگەڵ کۆمپانیا",
    "المبيعات الناجحة": "فرۆشتنی سەرکەوتوو",
    "المصروف يحتسب للعمليات الناجحة بتكلفة موثقة برد الشركة فقط. قيمة قائمة الشركة وقت الطلب ليست تسوية فعلية؛ إذا وجدت تكلفة غير موثقة يبقى الإجمالي غير معلوم.": "تێچوونەکە بۆ کارە سەرکەوتووەکان بە تێچووی بەڵگەدار تەنها لەگەڵ گەڕانەوەی کۆمپانیاکە حیسابی بۆ دەکرێت. بەهای لیستی کۆمپانیاکە لە کاتی داواکارییەکەدا یەکلاییکردنەوەی ڕاستەقینە نییە؛ ئەگەر تێچووی بێ بەڵگەنامە هەبێت، ئەوا کۆی گشتی بە نادیاری دەمێنێتەوە.",
    "مجموع مبالغ بيع العمليات الناجحة فقط ضمن نطاقك، عبر جميع التواريخ. الطلبات المعلقة والمرتجعة لا تدخل في هذا المجموع.": "کۆی بڕی فرۆشتنی تەنها مامەڵە سەرکەوتووەکان لە ناو دۆمەینەکەتدا، لە سەرجەم بەروارەکاندا. داواکارییە هەڵپەسێردراوەکان و گەڕێنراوەکان لەم کۆی گشتیدا نین.",
    "مبيعات الشبكة اليوم": "فرۆشتنی تۆڕی ئەمڕۆ",
    "البطاقات المباعة اليوم": "ئەمڕۆ کارت فرۆشرا",
    "ربح نقطة البيع اليوم": "قازانجی خاڵی فرۆشتن ئەمڕۆ",
    "ربح الوكيل اليوم": "ئەمڕۆ بریکارەکە سەرکەوت",
    "عرض الربح المشتق يتطلب صلاحية تكلفة التحميل.": "پیشاندانی قازانجی وەرگیراو پێویستی بە ڕەوایی تێچووی بارکردن هەیە.",
    "عمليات الطباعة الفاشلة": "کارەکانی چاپکردن شکستی هێنا",
    "عرض الربح يتطلب صلاحية تكلفة التحميل والفواتير.": "پیشاندانی قازانج پێویستی بە ڕەوایەتی تێچووی دابەزاندن و فاکتورەکان هەیە.",
    "الرصيد التشغيلي المتاح": "باڵانسی کارکردن بەردەستە",
    "البطاقات · الآن": "کارتەکان · ئێستا",
    "محفظة الحساب خارج نطاق الموظف.": "پۆرتفۆلیۆی ئەکاونتەکە لە دەرەوەی بازنەی کارمەنددایە.",
    "المخزون الخاص بالوكيل خارج نطاق الموظف.": "پشکی بریکارەکە لە دەرەوەی بازنەی کارمەندەکەدایە.",
    "الفروع والفروع الفرعية": "لق و لقی لاوەکی",
    "مفعّلة": "چالاک کراوە",
    "المحافظات المفعّلة": "پارێزگارەکان چالاک کراون",
    "لم تُنقل أرصدة نقدية سابقة موثقة إلى قاعدة البيانات.": "هیچ باڵانسێکی نەختینەی پێشووی بەڵگەدار نەگوازراوەتەوە بۆ بنکەدراوە.",
    "لا توجد خدمة لتسجيل قواعد أسعار مؤجلة؛ الأسعار المعتمدة تظهر في تقرير الأسعار.": "هیچ خزمەتگوزارییەک بۆ تۆمارکردنی یاساکانی نرخی دواخراو نییە؛ نرخە پەسەندکراوەکان لە ڕاپۆرتی نرخەکاندا دەردەکەون.",
    "يتطلب سجل الخدمات صلاحية عرض الخدمات الرقمية ومصدر طلباتها.": "تۆماری خزمەتگوزاری پێویستی بە توانای پیشاندانی خزمەتگوزارییە دیجیتاڵییەکان و سەرچاوەی داواکارییەکانیان هەیە.",
    "يتطلب التقرير صلاحية عرض الربط أو الخدمات الرقمية.": "ڕاپۆرتەکە داوا لە دەسەڵات دەکات کە خزمەتگوزاری پەیوەندی یان دیجیتاڵی پێشکەش بکات.",
    "عرض الأرشيف يتطلب صلاحية الحسابات المؤرشفة ضمن نطاقك.": "بینینی ئەرشیف پێویستی بە ڕەوایەتی ئەکاونتە ئەرشیفکراوەکانە لەناو دۆمەینەکەتدا.",
    "عرض آخر حضور وموقع يتطلب صلاحية الخريطة ضمن نطاق المستخدمين المسموحين.": "پیشاندانی دوا ئامادەبوون و شوێن پێویستی بەوەیە نەخشەکە لە چوارچێوەی بەکارهێنەرانی ڕێگەپێدراودا ڕەوا بێت.",
    "ضوابط أوقات المستخدمين لمالك حساب مدير النظام مع صلاحيات الأمن وضوابطه فقط.": "کۆنتڕۆڵی کاتی بەکارهێنەر سەر بە خاوەن ئەکاونتی بەڕێوەبەری سیستەمە کە تەنها دەسەڵات و کۆنترۆڵی ئەمنی هەیە.",
    "يتطلب سجل قرارات الإيقاف حساب النظام وصلاحيات عرض الأمن والتدقيق.": "لۆگی بڕیارەکانی ڕاگرتن پێویستی بە ئەکاونتی سیستەم و بینینی مۆڵەتی ئاسایش و وردبینی هەیە.",
    "لا يوجد سجل حجز مستقل لطلبات التمويل؛ حجوزات البيع تظهر في تقرير حجوزات البطاقات.": "هیچ تۆمارێکی سەربەخۆی حجزکردن بۆ داواکارییەکانی دارایی نییە؛ حجزکردنی فرۆشتن لە ڕاپۆرتی حجزکردنی کارتەکاندا دەردەکەوێت.",
    "مصدر هذا التقرير غير متاح للحساب أو لم يُفعّل بعد.": "سەرچاوەی ئەم ڕاپۆرتە بۆ ئەکاونتەکە بەردەست نییە یان تا ئێستا چالاک نەکراوە.",
    "تكلفة الشركة مخفية عن نقطة البيع؛ لا يوجد سعر شراء مستقل يتيح احتساب ربحها دون كشف هذه التكلفة.": "تێچووی کۆمپانیاکە لە خاڵی فرۆشتنەوە شاراوەتەوە؛ هیچ نرخێکی کڕینی سەربەخۆ نییە کە ڕێگە بە حیسابکردنی قازانجەکەی بدات بەبێ ئەوەی ئەم تێچوونە ئاشکرا بکات.",
