    "COALESCE(provider.name,CASE r.provider WHEN 'rabiaa' THEN 'الرابعة' WHEN 'topup' THEN 'التعبئة المباشرة' ELSE NULL END)": "COALESCE(ناوی دابینکەر،CASE r.provider کاتێک 'rabiaa' پاشان 'چوارەم' کاتێک 'topup' پاشان 'پڕکردنەوەی ڕاستەوخۆ' ELSE NULL END)",
